-- V254: Cadastros tributários versionados (Prompt 124)
CREATE TABLE fiscal_tax_catalog_versions (
    id              UUID            NOT NULL,
    catalog_type    VARCHAR(40)     NOT NULL,
    version_code    VARCHAR(40)     NOT NULL,
    source          VARCHAR(100)    NULL,
    imported_at     TIMESTAMPTZ     NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    imported_by     UUID            NULL,
    notes           VARCHAR(2000)   NULL,
    entry_count     INT             NOT NULL DEFAULT 0,
    CONSTRAINT pk_fiscal_tax_catalog_versions PRIMARY KEY (id),
    CONSTRAINT uk_ftcv_type_version UNIQUE (catalog_type, version_code)
);

CREATE TABLE fiscal_tax_catalogs (
    id                  UUID            NOT NULL,
    catalog_type        VARCHAR(40)     NOT NULL,
    code                VARCHAR(40)     NOT NULL,
    description         VARCHAR(500)    NOT NULL,
    uf                  CHAR(2)         NULL,
    extra_json          TEXT            NULL,
    valid_from          DATE            NOT NULL,
    valid_until         DATE            NULL,
    catalog_version     VARCHAR(40)     NOT NULL,
    source              VARCHAR(100)    NULL,
    status              VARCHAR(20)     NOT NULL DEFAULT 'ACTIVE',
    active              BOOLEAN         NOT NULL DEFAULT TRUE,
    created_at          TIMESTAMPTZ     NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    updated_at          TIMESTAMPTZ     NOT NULL DEFAULT (NOW() AT TIME ZONE 'UTC'),
    created_by          UUID            NULL,
    updated_by          UUID            NULL,
    version             BIGINT          NOT NULL DEFAULT 0,
    CONSTRAINT pk_fiscal_tax_catalogs PRIMARY KEY (id),
    CONSTRAINT ck_ftc_status CHECK (status IN ('ACTIVE', 'INACTIVE', 'DISCONTINUED')),
    CONSTRAINT ck_ftc_type CHECK (catalog_type IN (
        'NCM', 'CEST', 'CFOP', 'CST_ICMS', 'CSOSN', 'CST_IPI', 'CST_PIS', 'CST_COFINS',
        'ORIGEM_MERCADORIA', 'UNIDADE_TRIBUTAVEL', 'MODALIDADE_FRETE', 'BENEFICIO_FISCAL',
        'MUNICIPIO_IBGE', 'PAIS', 'UF', 'MEIO_PAGAMENTO_FISCAL', 'FINALIDADE_EMISSAO',
        'INDICADOR_PRESENCA', 'INDICADOR_INTERMEDIADOR'
    ))
);

CREATE UNIQUE INDEX uk_ftc_type_code_uf_ver
    ON fiscal_tax_catalogs (catalog_type, code, COALESCE(uf, ''), catalog_version);

CREATE INDEX idx_ftc_type_code ON fiscal_tax_catalogs (catalog_type, code);
CREATE INDEX idx_ftc_validity ON fiscal_tax_catalogs (catalog_type, valid_from, valid_until);

COMMENT ON TABLE fiscal_tax_catalogs IS 'Tabelas tributárias versionadas (Prompt 124) — códigos descontinuados permanecem';
COMMENT ON TABLE fiscal_tax_catalog_versions IS 'Histórico de importação/versão de catálogos fiscais';

